with ZipFile(review/'beon-sales-25s-project.zip','w',ZIP_DEFLATED) as z:
 for folder in ['src','public','scripts','review','exports']:
  for p in sorted((root/folder).rglob('*')):
   if p.is_file() and p.suffix!='.zip' and not p.name.startswith('check-'):z.write(p,Path('beon-sales-25s')/p.relative_to(root))
 for name in ['package.json','package-lock.json','tsconfig.json','remotion.config.ts','eslint.config.mjs','.prettierrc','.gitignore','README.txt','README.md','AUDIO-LICENSE.txt','narration.txt','asset-manifest.json']:
  z.write(root/name,Path('beon-sales-25s')/name)
